## Generates the concrete constraint DSL overloads for constraints.nim.
## Run with: nim c -r scripts/gen_dsl.nim
import strutils

let sides = @["Variable", "Term", "Expression"]
let relOps = [
  ("`<=`", "relLe"),
  ("`>=`", "relGe"),
  ("`==`", "relEq"),
  ("le", "relLe"),
  ("ge", "relGe"),
  ("eq", "relEq"),
]

var buf = newStringOfCap(1 shl 14)

buf.add """## Concrete comparison-operator overloads for the constraint DSL.
## Generated by scripts/gen_dsl.nim -- do not edit by hand.

func toConstraintExpr(value: Variable): Expression {.raises.} =
  toExpression(value)

func toConstraintExpr(value: Term): Expression {.raises.} =
  toExpression(value)

func toConstraintExpr(value: Expression): Expression =
  value

func toConstraintExpr(value: KiwiScalar): Expression {.raises.} =
  toExpression(value)

proc makeConstraintExpr(
    left, right: Expression, relation: Relation
): Constraint {.raises.} =
  newConstraint(left - right, relation)

"""

proc emit(buf: var string, op, a, b, rel: string) =
  buf.add "proc " & op & "*(left: " & a & "; right: " & b &
    "): Constraint {.raises.} =\n"
  buf.add "  makeConstraintExpr(toConstraintExpr(left), toConstraintExpr(right), " & rel & ")\n\n"

for a in sides:
  for b in sides:
    for (op, rel) in relOps:
      emit(buf, op, a, b, rel)
for a in sides:
  for (op, rel) in relOps:
    emit(buf, op, a, "KiwiScalar", rel)

# Scalar-left: `<=` is the flipped relGe (Nimony rewrites `x >= c` to `c <= x`).
for b in sides:
  buf.add "proc `<=`*(left: KiwiScalar; right: " & b & "): Constraint {.raises.} =\n"
  buf.add "  # Nimony rewrites `x >= c` to `c <= x`; keep the greater-than meaning.\n"
  buf.add "  makeConstraintExpr(toConstraintExpr(right), toConstraintExpr(left), relGe)\n\n"
  buf.add "proc `>=`*(left: KiwiScalar; right: " & b & "): Constraint {.raises.} =\n"
  buf.add "  makeConstraintExpr(toConstraintExpr(left), toConstraintExpr(right), relGe)\n\n"
  buf.add "proc `==`*(left: KiwiScalar; right: " & b & "): Constraint {.raises.} =\n"
  buf.add "  makeConstraintExpr(toConstraintExpr(left), toConstraintExpr(right), relEq)\n\n"
  for pair in [("le", "relLe"), ("ge", "relGe"), ("eq", "relEq")]:
    buf.add "proc " & pair[0] & "*(left: KiwiScalar; right: " & b & "): Constraint {.raises.} =\n"
    buf.add "  makeConstraintExpr(toConstraintExpr(left), toConstraintExpr(right), " & pair[1] & ")\n\n"

writeFile("src/kiwiberry/dsl_generated.nim", buf)
echo "wrote src/kiwiberry/dsl_generated.nim (" & $buf.len & " bytes)"
